18	public class AnimatableTransformParser {
19	
20	  private AnimatableTransformParser() {
21	  }
22	
23	
24	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
25	      "a",  // 1
26	      "p",  // 2
27	      "s",  // 3
28	      "rz", // 4
29	      "r",  // 5
30	      "o",  // 6
31	      "so", // 7
32	      "eo", // 8
33	      "sk", // 9
34	      "sa", // 10
35	      "rx", // 11
36	      "ry"  // 12
37	  );
38	  private static final JsonReader.Options ANIMATABLE_NAMES = JsonReader.Options.of("k");
39	
40	  public static AnimatableTransform parse(
41	      JsonReader reader, LottieComposition composition) throws IOException {
42	    AnimatablePathValue anchorPoint = null;
43	    AnimatableValue<PointF, PointF> position = null;
44	    AnimatableScaleValue scale = null;
45	    AnimatableFloatValue rotation = null;
46	    AnimatableIntegerValue opacity = null;
47	    AnimatableFloatValue startOpacity = null;
48	    AnimatableFloatValue endOpacity = null;
49	    AnimatableFloatValue skew = null;
50	    AnimatableFloatValue skewAngle = null;
51	    AnimatableFloatValue rotationX = null;
52	    AnimatableFloatValue rotationY = null;
53	    AnimatableFloatValue rotationZ = null;
54	
55	    boolean isObject = reader.peek() == JsonReader.Token.BEGIN_OBJECT;
56	    if (isObject) {
57	      reader.beginObject();
58	    }
59	    while (reader.hasNext()) {
60	      switch (reader.selectName(NAMES)) {
61	        case 0: // a
62	          reader.beginObject();
63	          while (reader.hasNext()) {
64	            switch (reader.selectName(ANIMATABLE_NAMES)) {
65	              case 0:
66	                anchorPoint = AnimatablePathValueParser.parse(reader, composition);
67	                break;
68	              default:
69	                reader.skipName();
70	                reader.skipValue();
71	            }
72	          }
73	          reader.endObject();
74	          break;
75	        case 1: // p
76	          position =
77	              AnimatablePathValueParser.parseSplitPath(reader, composition);
78	          break;
79	        case 2: // s
80	          scale = AnimatableValueParser.parseScale(reader, composition);
81	          break;
82	        case 3: // rz
83	          rotationZ = AnimatableValueParser.parseFloat(reader, composition, false);
84	          ensureValidRotationKeyframes(rotationZ, composition);
85	          break;
86	        case 4: // r
87	          /*
88	           * Sometimes split path rotation gets exported like:
89	           *         "rz": {
90	           *           "a": 1,
91	           *           "k": [
92	           *             {}
93	           *           ]
94	           *         },
95	           * which doesn't parse to a real keyframe.
96	           */
97	          rotation = AnimatableValueParser.parseFloat(reader, composition, false);
98	          ensureValidRotationKeyframes(rotation, composition);
99	          break;
100	        case 5: // o
101	          opacity = AnimatableValueParser.parseInteger(reader, composition);
102	          break;
103	        case 6: // so
104	          startOpacity = AnimatableValueParser.parseFloat(reader, composition, false);
105	          break;
106	        case 7: // eo
107	          endOpacity = AnimatableValueParser.parseFloat(reader, composition, false);
108	          break;
109	        case 8: // sk
110	          skew = AnimatableValueParser.parseFloat(reader, composition, false);
111	          break;
112	        case 9: // sa
113	          skewAngle = AnimatableValueParser.parseFloat(reader, composition, false);
114	          break;
115	        case 10: // rx
116	          rotationX = AnimatableValueParser.parseFloat(reader, composition, false);
117	          ensureValidRotationKeyframes(rotationX, composition);
118	          break;
119	        case 11: // ry
120	          rotationY = AnimatableValueParser.parseFloat(reader, composition, false);
121	          ensureValidRotationKeyframes(rotationY, composition);
122	          break;
123	        default:
124	          reader.skipName();
125	          reader.skipValue();
126	      }
127	    }
