1	package com.airbnb.lottie.animation.content;
2	
3	import android.graphics.Path;
4	import android.graphics.PointF;
5	import android.graphics.RectF;
6	
7	import androidx.annotation.Nullable;
8	
9	import com.airbnb.lottie.LottieDrawable;
10	import com.airbnb.lottie.LottieProperty;
11	import com.airbnb.lottie.animation.keyframe.BaseKeyframeAnimation;
12	import com.airbnb.lottie.animation.keyframe.FloatKeyframeAnimation;
13	import com.airbnb.lottie.model.KeyPath;
14	import com.airbnb.lottie.model.content.RectangleShape;
15	import com.airbnb.lottie.model.content.ShapeTrimPath;
16	import com.airbnb.lottie.model.layer.BaseLayer;
17	import com.airbnb.lottie.utils.MiscUtils;
18	import com.airbnb.lottie.value.LottieValueCallback;
19	
20	import java.util.List;
21	
22	public class RectangleContent
23	    implements BaseKeyframeAnimation.AnimationListener, KeyPathElementContent, PathContent {
24	  private final Path path = new Path();
25	  private final RectF rect = new RectF();
26	
27	  private final String name;
28	  private final boolean hidden;
29	  private final LottieDrawable lottieDrawable;
30	  private final BaseKeyframeAnimation<?, PointF> positionAnimation;
31	  private final BaseKeyframeAnimation<?, PointF> sizeAnimation;
32	  private final BaseKeyframeAnimation<?, Float> cornerRadiusAnimation;
33	
34	  private final CompoundTrimPathContent trimPaths = new CompoundTrimPathContent();
35	  /** This corner radius is from a layer item. The first one is from the roundedness on this specific rect. */
36	  @Nullable private BaseKeyframeAnimation<Float, Float> roundedCornersAnimation = null;
37	  private boolean isPathValid;
38	
39	  public RectangleContent(LottieDrawable lottieDrawable, BaseLayer layer, RectangleShape rectShape) {
40	    name = rectShape.getName();
41	    hidden = rectShape.isHidden();
42	    this.lottieDrawable = lottieDrawable;
43	    positionAnimation = rectShape.getPosition().createAnimation();
44	    sizeAnimation = rectShape.getSize().createAnimation();
45	    cornerRadiusAnimation = rectShape.getCornerRadius().createAnimation();
46	
47	    layer.addAnimation(positionAnimation);
48	    layer.addAnimation(sizeAnimation);
49	    layer.addAnimation(cornerRadiusAnimation);
50	
51	    positionAnimation.addUpdateListener(this);
52	    sizeAnimation.addUpdateListener(this);
53	    cornerRadiusAnimation.addUpdateListener(this);
54	  }
55	
56	  @Override
57	  public String getName() {
58	    return name;
59	  }
60	
61	  @Override
62	  public void onValueChanged() {
63	    invalidate();
64	  }
65	
66	  private void invalidate() {
67	    isPathValid = false;
68	    lottieDrawable.invalidateSelf();
69	  }
70	
71	  @Override
72	  public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
73	    for (int i = 0; i < contentsBefore.size(); i++) {
74	      Content content = contentsBefore.get(i);
75	      if (content instanceof TrimPathContent &&
76	          ((TrimPathContent) content).getType() == ShapeTrimPath.Type.SIMULTANEOUSLY) {
77	        TrimPathContent trimPath = (TrimPathContent) content;
78	        trimPaths.addTrimPath(trimPath);
79	        trimPath.addListener(this);
80	      } else if (content instanceof RoundedCornersContent) {
81	        roundedCornersAnimation = ((RoundedCornersContent) content).getRoundedCorners();
82	      }
83	    }
84	  }
85	
86	  @Override
87	  public Path getPath() {
88	    if (isPathValid) {
89	      return path;
90	    }
91	
92	    path.reset();
93	
94	    if (hidden) {
95	      isPathValid = true;
96	      return path;
97	    }
98	
99	    PointF size = sizeAnimation.getValue();
100	    float halfWidth = size.x / 2f;
101	    float halfHeight = size.y / 2f;
102	    float radius = cornerRadiusAnimation == null ?
103	        0f : ((FloatKeyframeAnimation) cornerRadiusAnimation).getFloatValue();
104	    if (radius == 0f && this.roundedCornersAnimation != null) {
105	      radius = Math.min(roundedCornersAnimation.getValue(), Math.min(halfWidth, halfHeight));
106	    }
107	    float maxRadius = Math.min(halfWidth, halfHeight);
108	    if (radius > maxRadius) {
109	      radius = maxRadius;
110	    }
111	
112	    // Draw the rectangle top right to bottom left.
113	    PointF position = positionAnimation.getValue();
114	
115	    path.moveTo(position.x + halfWidth, position.y - halfHeight + radius);
116	
117	    path.lineTo(position.x + halfWidth, position.y + halfHeight - radius);
118	
119	    if (radius > 0) {
120	      rect.set(position.x + halfWidth - 2 * radius,
121	          position.y + halfHeight - 2 * radius,
122	          position.x + halfWidth,
123	          position.y + halfHeight);
124	      path.arcTo(rect, 0, 90, false);
125	    }
126	
127	    path.lineTo(position.x - halfWidth + radius, position.y + halfHeight);
128	
129	    if (radius > 0) {
130	      rect.set(position.x - halfWidth,
131	          position.y + halfHeight - 2 * radius,
132	          position.x - halfWidth + 2 * radius,
133	          position.y + halfHeight);
134	      path.arcTo(rect, 90, 90, false);
135	    }
136	
137	    path.lineTo(position.x - halfWidth, position.y - halfHeight + radius);
138	
139	    if (radius > 0) {
140	      rect.set(position.x - halfWidth,
141	          position.y - halfHeight,
142	          position.x - halfWidth + 2 * radius,
143	          position.y - halfHeight + 2 * radius);
144	      path.arcTo(rect, 180, 90, false);
